  function comparison(type){const now=type==='income'?view.summary.income:view.summary.netExpense,prev=type==='income'?view.previous.income:view.previous.netExpense,diff=now-prev,ratio=prev>0?Math.abs(diff/prev*100).toLocaleString('tr-TR',{maximumFractionDigits:1})+'%':null;return `<p class="finance-comparison ${type==='income'?diff<0?'budget-negative':'budget-income':diff>0?'budget-negative':'budget-income'}">${diff>0?'+':diff<0?'−':''}${currency(Math.abs(diff))}${ratio?' · '+ratio+' '+(diff<0?'azalış':diff>0?'artış':'değişim yok'):' · Önceki ay sıfır; yüzde hesaplanmaz'}<small>Önceki aya göre${month===view.today.slice(0,7)?' · Bu ay henüz tamamlanmadı':''}</small></p>`;}
  function transactionStatistics(type){const from=month+'-01',to=lastDay(month),summary=view.summary,cats={};for(const t of view.transactions.filter(t=>t.date>=from&&t.date<=to&&t.date<=view.today&&(type==='income'?t.type==='income':['expense','refund'].includes(t.type))))for(const part of t.splits||[]){const n=Math.round(part.amount/t.amount*t.baseAmount);cats[part.categoryId]=(cats[part.categoryId]||0)+(t.type==='refund'?-n:n);}return `<article class="budget-card"><h3>${type==='income'?'Bu ayın gelirleri':'Bu ayın giderleri'}</h3><strong class="finance-section-total ${type==='income'?'budget-income':''}">${currency(type==='income'?summary.income:summary.netExpense)}</strong>${comparison(type)}${donut(cats)}<p class="budget-muted">İstatistik seçilen ayın bugün itibarıyla gerçekleşmiş kayıtlarını kapsar; aşağıdaki filtreler yalnız işlem listesini daraltır.</p></article>`;}
  function paymentGroups(rows,previewOnly=false){const today=view.today,week=new Date(today+'T12:00:00');week.setDate(week.getDate()+7);const weekEnd=week.getFullYear()+'-'+String(week.getMonth()+1).padStart(2,'0')+'-'+String(week.getDate()).padStart(2,'0'),current=today.slice(0,7),groups=[['Gecikmiş',rows.filter(o=>o.date<today)],['Önümüzdeki 7 gün',rows.filter(o=>o.date>=today&&o.date<=weekEnd)],['Bu ayın diğer ödemeleri',rows.filter(o=>o.date>weekEnd&&o.date.startsWith(current))],['Sonraki ay',rows.filter(o=>o.date>weekEnd&&!o.date.startsWith(current))]];let remaining=previewOnly?4:Infinity;return groups.filter(([,r])=>r.length).map(([name,r])=>{const show=r.slice(0,Math.min(remaining,100));remaining-=show.length;return show.length?`<section class="finance-payment-group"><h4>${name}</h4>${show.map(occurrenceRow).join('')}${!previewOnly&&r.length>100?'<p>İlk 100 kayıt gösteriliyor. Takvimden bir gün seçerek daraltabilirsin.</p>':''}</section>`:'';}).join('')||'<p class="budget-muted">Bu ay veya sonraki ay için bekleyen kayıt yok.</p>';}
