  function render(){
    if(!view)return;
    const rawView=view;if(tab==='reports')view=window.NeroFinanceFeatures?.reportView(view)||view;view=window.NeroFinanceFeatures?.groupView(view)||view;
    $('budget-month-caption').textContent=new Intl.DateTimeFormat('tr-TR',{month:'long',year:'numeric'}).format(new Date(month+'-01T12:00:00'));
    root.dataset.textSize=view.preferences.textSize;root.dataset.financeTheme=view.preferences.financeTheme||'modern';root.dataset.financePage=tab;
    document.documentElement.dataset.financeTheme=root.dataset.financeTheme;
    root.querySelector('.finance-side-title').textContent=({'premium-black':'Premium Black','financial-dashboard':'Finans Merkezi'})[root.dataset.financeTheme]||'Bütçe';
    $('budget-page-title').textContent=({overview:'Genel bakış',transactions:'İşlemler',accounts:'Hesaplar',budgets:['premium-black','financial-dashboard'].includes(root.dataset.financeTheme)?'Birikim ve bütçe':'Bütçeler',plans:'Ödemeler',reports:'Raporlar',calendar:'Takvim',handbook:'Finans Akademisi'})[tab];
    const size=$('budget-text-size');if(size)size.value=view.preferences.textSize;
    document.querySelectorAll('[data-budget-tab]').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.budgetTab===tab));b.tabIndex=b.dataset.budgetTab===tab?0:-1;});
    const context={run:(action,id)=>actions[action]?.(id),view,month,range:pbRange,cursor:pbCursor,focus:tab==='overview'?pbFocus:'all',currency,icon,category,account,when,opts,help,meter,budgetCategory,transactionRow,sortNewest,paymentGroups,brandIcon,onboarding,transactions,filters,transactionStatistics,planFilter,calendar,handbook,monthlySummary,trendChart,categoryRows,academyArea,academyModule,bookFilter,bookMode,academyList,searchTransactions};
    if(root.dataset.financeTheme==='financial-dashboard'){
      window.NeroPremiumUI.detach();window.NeroFinancialUI.mount(content,tab,context);
    }else if(root.dataset.financeTheme==='premium-black'){
      window.NeroFinancialUI.detach();window.NeroPremiumUI.mount(content,tab,context);
    }else{
      window.NeroFinancialUI.detach();window.NeroPremiumUI.detach();content.innerHTML=({overview,transactions,accounts,budgets,plans,reports,calendar,handbook}[tab])();
    }
    window.NeroFinanceFeatures?.update(context,tab);view=rawView;
  }
  function field(name,label,value='',type='text',extra=''){if(type==='date')return `<label>${esc(label)}<span class="finance-date"><input name="${esc(name)}" data-budget-date type="text" value="${esc(when(value))}" placeholder="GG.AA.YYYY" inputmode="numeric" ${extra}><input type="date" class="finance-native-date" data-date-for="${esc(name)}" value="${esc(value)}" aria-label="${esc(label)} takvimden seç"></span></label>`;return `<label>${esc(label)}${['opening','limit','cutDay','dueDay','target'].includes(name)?help(name==='opening'?'balance':name==='target'?'goals':'card'):''}<input name="${esc(name)}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
